 * @throws If the token is invalid, expired, or malformed.
 */
async function verifyJwt<T extends JWTPayload = JWTPayload>(
  token: string,
  key: KeyLike | Uint8Array,
  options?: { algorithms?: string[]; issuer?: string; audience?: string }
): Promise<T> {
