Here is a clean, type-safe implementation using `jose`'s `jwtVerify`. 

This handles symmetric secrets (e.g., `HS256`), supports a generic payload type, and checks standard claims like `issuer` and `audience`:

```typescript
import { jwtVerify, type JWTPayload, errors } from 'jose';

export interface VerifyJwtOptions {
  issuer?: string;
  audience?: string | string[];
  clockTolerance?: number | string; // e.g., '5s' or 5 (seconds)
}

/**
 * Verifies a JWT using a symmetric secret string.
 * Throws specific `jose.errors` (e.g., JWTExpired, JWTClaimValidationFailed) on failure.
 */
export async function verifyJwt<T extends JWTPayload = JWTPayload>(
  token: string,
  secret: string,
  options?: VerifyJwtOptions
): Promise<T> {
  const secretKey = new TextEncoder().encode(secret);

  const { payload } = await jwtVerify(token, secretKey, {
    issuer: options?.issuer,
    audience: options?.audience,
    clockTolerance: options?.clockTolerance,
  });

  return payload as T;
}
```

