interface AppUserPayload extends JWTPayload {
  userId: string;
  role: 'admin' | 'user';
}

async function handleRequest(rawAuthHeader: string) {
  const token = rawAuthHeader.replace(/^Bearer\s+/i, '');

  try {
    const payload = await verifyJwt<AppUserPayload>(
      token, 
      process.env.JWT_SECRET!,
      {
        issuer: 'urn:myapp:issuer',
        audience: 'urn:myapp:audience',
      }
    );

    console.log(`Authenticated user: ${payload.userId} (${payload.role})`);
    return payload;
  } catch (err) {
    if (err instanceof errors.JWTExpired) {
      // Token is structurally valid but expired
      throw new Error('Session expired');
    }
    if (err instanceof errors.JWTInvalid || err instanceof errors.JWTClaimValidationFailed) {
      // Tampered, bad signature, or wrong issuer/audience
      throw new Error('Invalid token');
    }
    throw err;
  }
}
