The key detail people usually trip over with `jose` is that it expects keys as a `Uint8Array` or a `CryptoKey`, not a raw string. 

```typescript
import { jwtVerify, type JWTPayload, errors } from 'jose';

export interface VerifyTokenOptions {
  issuer?: string;
  audience?: string;
  algorithms?: string[];
}

export type VerifyResult<T> =
  | { success: true; payload: T & JWTPayload }
  | { success: false; error: 'EXPIRED' | 'INVALID' | 'UNKNOWN'; message: string };

/**
 * Verifies a standard HMAC/symmetric JWT using `jose`.
 */
export async function verifyJwt<T extends Record<string, unknown> = Record<string, unknown>>(
  token: string,
  secret: string,
  options: VerifyTokenOptions = {}
): Promise<VerifyResult<T>> {
  try {
    const encodedSecret = new TextEncoder().encode(secret);

    const { payload } = await jwtVerify(token, encodedSecret, {
      issuer: options.issuer,
      audience: options.audience,
      algorithms: options.algorithms ?? ['HS256'],
    });

    return {
      success: true,
      payload: payload as T & JWTPayload,
    };
  } catch (err) {
    if (err instanceof errors.JWTExpired) {
      return { success: false, error: 'EXPIRED', message: 'Token has expired.' };
    }

    if (
      err instanceof errors.JWTInvalid ||
      err instanceof errors.JWSSignatureVerificationFailed ||
      err instanceof errors.JWTClaimValidationFailed
    ) {
      return { success: false, error: 'INVALID', message: err.message };
    }

    return {
      success: false,
      error: 'UNKNOWN',
      message: err instanceof Error ? err.message : 'An unexpected error occurred.',
    };
  }
}
```

