```ts
import {
  createRemoteJWKSet,
  jwtVerify,
  type JWTPayload,
  type JWTVerifyOptions,
} from "jose";

export interface AccessTokenClaims extends JWTPayload {
  sub: string;
  scope?: string;
  roles?: string[];
}

interface JwtVerifierConfig {
  jwksUrl: string;
  issuer: string;
  audience: string;
  algorithms?: JWTVerifyOptions["algorithms"];
}

export function createJwtVerifier(config: JwtVerifierConfig) {
  // Create this once so jose can cache keys and handle key rotation efficiently.
  const jwks = createRemoteJWKSet(new URL(config.jwksUrl));

  return async function verifyAccessToken(
    token: string,
  ): Promise<AccessTokenClaims> {
    if (!token || typeof token !== "string") {
      throw new Error("Missing access token");
    }

    const { payload } = await jwtVerify<AccessTokenClaims>(token, jwks, {
      issuer: config.issuer,
      audience: config.audience,

      // Never blindly trust the algorithm supplied by the token.
      algorithms: config.algorithms ?? ["RS256"],

      // Optional tolerance for small clock differences between servers.
      clockTolerance: 5,
    });

    // jose validates the signature and standard claims, but custom required
    // claims should be checked explicitly.
    if (!payload.sub) {
      throw new Error("Token is missing subject claim");
    }

    return payload;
  };
}
```

